UPDATE CHAT_ROOM R
JOIN CONTENT_MASTER CM ON CM.CONTENT_ID = R.CONTENT_ID
SET R.TITLE = #{title}
WHERE R.ROOM_ID = #{id}
  AND CM.USER_ID = #{userId}
  AND CM.IS_DELETED = 'N'

